insert into lessons (id, unit_id, title, intro, visual, sections, sort_order) values
  ('comp-rule', 'en-c7-grammar', 'Sifət dərəcələri qaydası', 'İki və ya daha çox şeyi müqayisə edək. Gəl öyrənək!', null, '[{"heading":"Müqayisə dərəcəsi (-er / more)","body":"İki şeyi müqayisə edərkən: tall → taller, big → bigger. Uzun sözlərdə ''more'': beautiful → more beautiful. ''than'' ilə: Tom is taller than Sam."},{"heading":"Üstünlük dərəcəsi (-est / most)","body":"Ən yüksək dərəcə: tall → the tallest, big → the biggest. Uzun sözlərdə ''the most'': the most beautiful."},{"heading":"Qeyri-qaydalı","body":"good → better → the best. bad → worse → the worst."}]'::jsonb, 0),
  ('comp-vocab', 'en-c7-vocab', 'Sifətlər (8 söz)', 'Müqayisə üçün 8 yeni sifət öyrənək.', null, '[{"heading":"Yeni sözlər (8 sifət)","body":"tall — hündür · short — qısa/alçaq · fast — sürətli · slow — yavaş · strong — güclü · young — gənc/cavan · clever — ağıllı · heavy — ağır"},{"heading":"Məsləhət","body":"Bu sifətlərin müqayisə formasını da yadda saxla: taller, faster, stronger, heavier..."}]'::jsonb, 0),
  ('comp-listen', 'en-c7-listening', 'Dinlə və seç: müqayisə', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('comp-read', 'en-c7-reading', 'Reading: Animals', 'Qısa mətni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"Animals are different. The cheetah is the fastest animal. It can run very fast. The elephant is the biggest animal on land. It is very heavy. The giraffe is the tallest animal. Its neck is very long. A mouse is smaller than a cat, but a cat is smaller than a dog. The blue whale is the biggest animal in the world."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('comp-write', 'en-c7-writing', 'Cümlə qur: müqayisə', 'Sözləri düzgün sıraya düz və müqayisə cümləsi qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas. Müqayisə: X is + sifət-er + than + Y. Üstünlük: the + sifət-est."}]'::jsonb, 0),
  ('modal-rule', 'en-c8-grammar', 'Modal fellər qaydası', 'can, must, should — modal fellər. Nə vaxt hansını işlətməli?', null, '[{"heading":"can — bacarıq / icazə","body":"Bir işi bacarmaq və ya icazə: I can swim. Can I go? Modaldan sonra fel əsas formadadır (can swim, NOT can swims)."},{"heading":"must — məcburiyyət","body":"Vacib, məcburi iş: You must stop. İnkar mustn''t = qadağan: You mustn''t run here."},{"heading":"should — məsləhət","body":"Tövsiyə/məsləhət: You should sleep early. İnkar shouldn''t: You shouldn''t eat too much."}]'::jsonb, 0),
  ('modal-vocab', 'en-c8-vocab', 'Bacarıq felləri (8 söz)', '''can'' ilə işlədəcəyimiz 8 yeni fel öyrənək.', null, '[{"heading":"Yeni sözlər (8 fel)","body":"jump — tullanmaq · climb — dırmaşmaq · fly — uçmaq · draw — rəsm çəkmək · drive — sürmək · fix — təmir etmək · ride — minmək · count — saymaq"},{"heading":"Məsləhət","body":"Bu felləri ''can'' ilə işlət: I can jump. She can draw. A bird can fly."}]'::jsonb, 0),
  ('modal-listen', 'en-c8-listening', 'Dinlə və seç: can / must / should', 'Cümləni dinlə və düzgün cavabı seç.', null, '[{"heading":"Necə işləyir?","body":"«Dinlə» düyməsinə bas, cümləni eşit və düzgün variantı seç. İstədiyin qədər təkrar dinlə."}]'::jsonb, 0),
  ('modal-read', 'en-c8-reading', 'Reading: School rules', 'Qısa mətni oxu və suallara cavab ver.', null, '[{"heading":"Read the text (Mətni oxu)","body":"At our school there are some rules. You must come to school on time. You must listen to the teacher. You should do your homework every day. You can play in the yard at break time. You mustn''t run in the classroom. You shouldn''t shout. Good students always follow the rules."},{"heading":"İpucu","body":"Sualı oxu, cavabı mətndə tap. Lazım olsa mətnə yenidən bax."}]'::jsonb, 0),
  ('modal-write', 'en-c8-writing', 'Cümlə qur: can / must / should', 'Sözləri düzgün sıraya düz və modal cümlə qur.', null, '[{"heading":"Necə işləyir?","body":"Sözlərə sıra ilə bas. Quruluş: kim + modal (can/must/should) + fel (əsas forma)."}]'::jsonb, 0)
